update public.fields set verification_status='verified_against_standard', verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren zur Identifizierung und Begründung des Bezugsszenarios auswählen oder festlegen, beschreiben und anwenden. | Die Begründung des Treibhausgasbezugsszenarios sollte die wahrscheinliche zukünftige Entwicklung des Bezugsszenarios (THG-QSS) berücksichtigen, um den Grundsatz der Konservativität (4.7) zu erfüllen. — printed p.33', verification_note='md-verified 2026-09-05 (§6.4, printed p.33) [VC]', verified_at=now() where id='ed005e63-f616-426d-8c68-e2b7830ef3ca' and verification_status not in ('verified_against_standard','corrected');
-- baseline_conservative
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Entwicklung des Treibhausgasbezugsszenarios muss der Antragsteller des Projekts die Annahmen, Werte und Verfahren auswählen, die sicherstellen, dass die Reduktionen von Treibhausgasemissionen oder Steigerungen des Entzugs nicht überschätzt werden und diese begründen. — printed p.33', verification_note='md-verified 2026-09-05 (§6.4, printed p.33) [VC]', verified_at=now() where id='144c77b7-25b8-48af-ac41-560b48bb7c36' and verification_status not in ('verified_against_standard','corrected');
-- additionality_demonstrated
update public.fields set verification_status='verified_against_standard', verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren auswählen oder festlegen, begründen und anwenden, um nachzuweisen, dass die Reduktionen von Treibhausgasemissionen oder Steigerungen des Entzugs des Projektes zusätzlich im Vergleich zu dem festgelegten Treibhausgasbezugsszenario sind. — printed p.33', verification_note='md-verified 2026-09-05 (§6.4, printed p.33) [VC]', verified_at=now() where id='f8eaa9b4-513b-4fb8-9579-b9c30a514604' and verification_status not in ('verified_against_standard','corrected');

-- ---- worksheet ISO-14064-2-05 ----
-- baseline_ssr
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Identifizierung von für das Bezugsszenario relevanten THG-QSS muss der Antragsteller des Projekts: | a) die bei der Identifizierung von für das Projekt relevanten THG-QSS angewendeten Kriterien und Verfahren berücksichtigen; | b) bei Bedarf zusätzliche Kriterien zur Identifizierung von relevanten THG-QSS erläutern und anwenden; | c) die im Zusammenhang mit dem Projekt identifizierten THG-QSS mit denen vergleichen, die im Bezugsszenario identifiziert wurden. — printed p.34', verification_note='md-verified 2026-09-05 (§6.5 a)-c), printed p.34) [VC]', verified_at=now() where id='0ea16ba7-eb8f-4742-b03a-e270aaf4006b' and verification_status not in ('verified_against_standard','corrected');
-- ssr_selection_mode
update public.fields set verification_status='verified_against_standard', verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren zur Auswahl von THG-QSS entweder für die regelmäßige Überwachung oder für die Abschätzung auf der Grundlage geeigneter und zuverlässiger Daten auswählen oder festlegen. — printed p.34', verification_note='md-verified 2026-09-05 (§6.6, printed p.34) [VC]', verified_at=now() where id='ecfee535-a569-487b-9bf5-fae3903b790e' and verification_status not in ('verified_against_standard','corrected');
-- ssr_exclusion_justification
update public.fields set verification_status='verified_against_standard', verification_quote='Der Projektantragsteller muss eine Begründung vorbringen, wenn er keine THG-QSS, wie im Treibhausgasbezugsszenario angegeben, für die regelmäßige Überwachung ausgewählt hat. — printed p.34', verification_note='md-verified 2026-09-05 (§6.6, printed p.34) [VC] — Der Satz ist die Quelle fuer DIESES Feld, nicht fuer den Enum ssr_selection_mode - REQ-12 zitiert ihn dennoch dort. Siehe STAGED C-2.', verified_at=now() where id='9f3b484e-4ef8-4abc-a64f-fd6875bac83f' and verification_status not in ('verified_against_standard','corrected');

-- ---- worksheet ISO-14064-2-06 ----
-- activity_data
update public.fields set verification_status='verified_against_standard', verification_quote='Faktor, der die THG-Aktivitätsdaten mit der Emisión de THG(3.1.5) verbindet | Faktor, der die THG-Aktivitätsdaten mit dem THGEntzug(3.1.6) verbindet — printed pp.17-18', verification_note='md-verified 2026-09-05 (§3.1.9/§3.1.10, printed pp.17-18) [VC] — Vorbehalt: die Norm definiert "Aktivitaetsdaten" NICHT als eigenen Begriff; sie erscheinen nur als "THG-Aktivitaetsdaten" innerhalb der Faktordefinitionen 3.1.9/3.1.10. Die Einheit "unit-dependent" im Encoding ist EKOWAI-Konvention, keine Normvorgabe.', verified_at=now() where id='e0179bf1-36b5-485b-adef-1b5de22ac06c' and verification_status not in ('verified_against_standard','corrected');
-- emission_factor
update public.fields set verification_status='verified_against_standard', verification_quote='Gegebenenfalls muss der Antragsteller des Projekts Treibhausgasemissions- oder -entzugsfaktoren auswählen oder entwickeln, morir: | - aus einer anerkannten Quelle stammen, | — für die betreffende Treibhausgasquelle oder - senke geeignet sind, | — zum Zeitpunkt derquantantn Bestimmung aktuell sind, | - der vorgesehenen Verwendung des Treibhausgasberichtes entsprechen. — printed p.35', verification_note='md-verified 2026-09-05 (§6.7, printed p.35) [VC] — Vorbehalt: die Anforderung steht unter "Gegebenenfalls" (bedingt); die Norm nennt weder Zahlenwerte noch eine Einheit fuer Emissionsfaktoren. Das Feld traegt im Encoding keine Einheit - siehe STAGED B-1.', verified_at=now() where id='ecba1225-735a-47c2-9f2e-04b6332eea9a' and verification_status not in ('verified_against_standard','corrected');
-- gwp
update public.fields set verification_status='verified_against_standard', verification_quote='Index auf der Grundlage der Strahlungseigenschaften von $\operatorname{THG}(3.1 .1)$, der den Strahlungsantrieb nach einer Impulsemission einer Masseeinheit eines gegebenen THG in der heutigen Atmosphäre über einen gewählten Zeitrahmen im Vergleich zum Strahlungsantrieb von Kohlendioxid (CO2) señorita | Sofern anwendbar, muss der Projektantragsteller die Menge jeder Art von Treibhausgas unter Anwendung des entsprechenden Treibhauspotentials in Einheiten von CO 2 e umrechnen. — printed pp.19, 36', verification_note='md-verified 2026-09-05 (§3.1.14 + §6.8, printed pp.19, 36) [VC] — Vorbehalt: die Norm nennt keinen GWP-Zahlenwert und keinen Zeithorizont; 3.1.14 Anm. 1 verweist auf den juengsten IPCC-Sachstandsbericht. GWP bleibt damit eine Auswahl des Ingenieurs (SR-2), kein standard_fixed-Wert.', verified_at=now() where id='64adbb96-d183-461e-ac7f-6f881b3c7717' and verification_status not in ('verified_against_standard','corrected');
-- ssr_emission_co2e
update public.fields set verification_status='verified_against_standard', verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren oder Methoden zur quantumn Bestimmung von Treibhausgasemissionen und/ oder entzogenen Mengen für ausgewählte THGQSS (siehe 6.6) auswählen oder festlegen. | Wenn zusammengefasste Treibhausgasemissionen en CO2e anstelle einzelner Treibhausgasemissionen verwendet werden, muss der Grad der Zusammenführung mit den QSS angegeben werden, die Bedürfnisse des vorgesehenen Anwenders erfüllen undmitdenverwendeten Quantifizierungsverfahren konsistent sein. — printed pp.34-35', verification_note='md-verified 2026-09-05 (§6.7, printed pp.34-35) [VC]', verified_at=now() where id='9d41d3d5-1999-4c03-b02f-688f87cce01e' and verification_status not in ('verified_against_standard','corrected');
-- E_project
update public.fields set verification_status='verified_against_standard', verification_quote='a) jedes relevante Treibhausgas für jede(n) THG-QSS, die/der für das Projekt relevante ist; — printed p.35', verification_note='md-verified 2026-09-05 (§6.7 a), printed p.35) [VC] — Vorbehalt: 6.7 a) verlangt die getrennte Bestimmung je THG und je projektrelevantem QSS. Im Encoding summiert EQ-02 dasselbe Symbol wie EQ-03 - siehe STAGED B-2.', verified_at=now() where id='230588d5-cfcb-4d8d-83bf-d7ca9dc92e76' and verification_status not in ('verified_against_standard','corrected');
-- E_baseline
update public.fields set verification_status='verified_against_standard', verification_quote='b) jede(n) THG-QSS, die/der für das Bezugsszenario ist relevante. — printed p.35', verification_note='md-verified 2026-09-05 (§6.7 b), printed p.35) [VC] — Vorbehalt: 6.7 b) verlangt die getrennte Bestimmung fuer die bezugsszenariorelevanten QSS. Im Encoding summiert EQ-03 dasselbe Symbol wie EQ-02, so dass Projekt und Bezugsszenario rechnerisch nicht getrennt sind - siehe STAGED B-2.', verified_at=now() where id='4a507902-964a-47e8-a782-1c82149e6704' and verification_status not in ('verified_against_standard','corrected');
-- permanence_risk
update public.fields set verification_status='verified_against_standard', verification_quote='Der Antragsteller des Projekts muss Kriterien, Verfahren und/oder Methoden zur Abschätzung des Risikos, dass eine Reduktion der Treibhausgasemissionen oder Steigerung des Entzugs rückgängig gemacht wird (dh die Dauerhaftigkeit einer Reduktion der Treibhausgasemissionen oder Steigerung des Entzugs und fest). — printed p.35', verification_note='md-verified 2026-09-05 (§6.7, printed p.35) [VC] — Quellendefekt: der deutsche Satz bricht im Transkript UND im Quell-PDF ab ("... und fest)."); der vollstaendige Wortlaut ("festlegen und anwenden") ist nur in der spanischen Spalte lesbar. Verbatim uebernommen wie gedruckt.', verified_at=now() where id='21423fdc-d891-46d1-8a8d-a1a3abc352e1' and verification_status not in ('verified_against_standard','corrected');

-- ---- worksheet ISO-14064-2-07 ----
-- leakage
update public.fields set verification_status='verified_against_standard', verification_quote='Treibhausgasquelle (3.1.2), Treibhausgassenke (3.1.3) y Treibhausgasspeicher(3.1.4), die durch ein Proyecto THG(3.2.3) im Zusammenhang mit Änderungen der Marktnachfrage oder des Marktangebots zugehöriger Produkte oder Dienstleistungen oder durch physische Verschiebung beeinflusst werden | Anmerkung 2 zum Begriff: Die Verschiebung vonReduktion von Treibhausgasemissionen(3.1.7) ordenSteigerungen des Entzugs von Treibhausgasen(3.1.8) durch betroffene THG-QSS wird oft als Verlagerung bezeichnet. — printed p.18', verification_note='md-verified 2026-09-05 (§3.1.11, printed p.18) [VC] — Vorbehalt: die Norm nennt "Verlagerung" (leakage) nur in der Begriffsanmerkung 3.1.11 Anm. 2 und rechnet sie ueber die betroffenen THG-QSS ein; ein eigenes Leakage-Glied in der Differenzformel druckt sie NICHT. Das Feld wird von keiner Gleichung konsumiert - siehe STAGED B-3.', verified_at=now() where id='91a79718-8bd0-4b97-bc7a-50704dfec272' and verification_status not in ('verified_against_standard','corrected');
