update public.fields set verification_status='verified_against_standard', verification_quote='Wenn der Antragsteller des Projekts eine öffentliche Erklärung über Treibhausgase herausgibt, die die Übereinstimmung mit diesem Dokument beansprucht, muss er Folgendes veröffentlichen: | a) eine unabhängige Verifizierungs- oder Validierungserklärung von Dritten, die nach ISO 14064-3 erstellt wurde, oder | b) einen Treibhausgasbericht, der mindestens Folgendes enthält: | 1) den Namen des Antragstellers des Projekts; — printed pp.38-40', verification_note='md-verified 2026-09-05 (§6.13 b) 1)-15), printed pp.38-40) [VC] — Vorbehalt: die Norm gibt eine ALTERNATIVE a) ODER b); Punkt b) 15) ist in der deutschen Spalte leer gedruckt ("15).") - Inhalt nur in der spanischen Spalte. Siehe STAGED A-8/C-1.', verified_at=now() where id='b0ed9ed0-faf8-493f-b9f9-dd9943e02f9b' and verification_status not in ('verified_against_standard','corrected');


