-- EQ-01: ssr_emission_co2e = activity_data * emission_factor * gwp
update public.equations set verification_quote='Faktor, der die THG-Aktivitätsdaten mit der Emisión de THG(3.1.5) verbindet | Gegebenenfalls muss der Antragsteller des Projekts Treibhausgasemissions- oder -entzugsfaktoren auswählen oder entwickeln, morir: | Sofern anwendbar, muss der Projektantragsteller die Menge jeder Art von Treibhausgas unter Anwendung des entsprechenden Treibhauspotentials in Einheiten von CO 2 e umrechnen. — printed pp.17, 35, 36', verification_note=trim(both ' | ' from coalesce(nullif(verification_note,''),'') || ' | md-verified 2026-09-05 (§3.1.9 + §6.7 + §6.8, printed pp.17, 35, 36) [VC] — Die Norm DRUCKT KEINE FORMEL. Das Rechengeruest Aktivitaetsdaten x Faktor x GWP ist aus 3.1.9 (der Faktor verbindet Aktivitaetsdaten mit der Emission), 6.7 (Faktorauswahl) und 6.8 (GWP-Umrechnung in CO2e) abgeleitet - Synthese des Encodings, keine gedruckte Gleichung.'), verified_at=now() where id='1946f6f0-ee76-4d4f-a0a0-b7240196e734' and verification_quote is null;
-- EQ-02: E_project = SUM(ssr_emission_co2e)
update public.equations set verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren oder Methoden zur quantumn Bestimmung von Treibhausgasemissionen und/ oder entzogenen Mengen für ausgewählte THGQSS (siehe 6.6) auswählen oder festlegen. | a) jedes relevante Treibhausgas für jede(n) THG-QSS, die/der für das Projekt relevante ist; — printed pp.34-35', verification_note=trim(both ' | ' from coalesce(nullif(verification_note,''),'') || ' | md-verified 2026-09-05 (§6.7 a), printed pp.34-35) [VC] — Die Norm druckt keine Summenformel; 6.7 a) fordert die getrennte quantitative Bestimmung je THG und je projektrelevantem QSS - die Aggregation ist Synthese des Encodings.'), verified_at=now() where id='a6559b54-578c-4ba8-b224-37345a1269fe' and verification_quote is null;
-- EQ-03: E_baseline = SUM(ssr_emission_co2e)
update public.equations set verification_quote='Der Antragsteller des Projekts muss Kriterien und Verfahren oder Methoden zur quantumn Bestimmung von Treibhausgasemissionen und/ oder entzogenen Mengen für ausgewählte THGQSS (siehe 6.6) auswählen oder festlegen. | b) jede(n) THG-QSS, die/der für das Bezugsszenario ist relevante. — printed pp.34-35', verification_note=trim(both ' | ' from coalesce(nullif(verification_note,''),'') || ' | md-verified 2026-09-05 (§6.7 b), printed pp.34-35) [VC] — Die Norm druckt keine Summenformel; 6.7 b) fordert die getrennte quantitative Bestimmung fuer jeden bezugsszenariorelevanten QSS. WARNUNG: EQ-02 und EQ-03 summieren im Encoding DASSELBE Symbol ssr_emission_co2e, es gibt kein Szenario-Unterscheidungsmerkmal - siehe STAGED B-2.'), verified_at=now() where id='a7d36f0e-158e-4ef9-8c48-918ead93fa85' and verification_quote is null;
-- EQ-04: emission_reduction = E_baseline - E_project
update public.equations set verification_quote='Reduktionen der Treibhausgasemissionen oder Steigerungen des Entzugs müssen als Differenz zwischen den Treibhausgasemissionen und/oder entzogenen Mengen von den THG-QSS, die für das Projekt sind relevante, und denen, die für das Bezugsszenario sind relevante, quantitativ bestimmt werden. — printed p.36', verification_note=trim(both ' | ' from coalesce(nullif(verification_note,''),'') || ' | md-verified 2026-09-05 (§6.8, printed p.36) [VC] — Die Differenzbildung ist gedruckt; die Vorzeichenrichtung (Bezugsszenario minus Projekt) folgt aus 3.1.7 "quantifizierte Reduzierung ... zwischen einem Bezugsscenario und dem Projekt".'), verified_at=now() where id='a7244a73-ebd4-481d-a867-5432768cdd70' and verification_quote is null;
